```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

@base <http://example.org/onto/assessment#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:comment "Ontology of educational assessment, test typology, validity/reliability theory, and related constructs, modeled from a corpus describing educational assessment. Where the corpus presents conflicting classification claims (coordinate lists vs. subordination), both axiomatizations are encoded and the tension is documented in rdfs:comment annotations." .

#################################################################
# ROOT CLASSES
#################################################################

ea:EducationalConcept a owl:Class .
ea:ClassificationCategory a owl:Class .

ea:Assessment a owl:Class ; rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Learning a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:AssessmentQuality a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:AssessmentTool a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:EducationalActor a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:EducationalPhenomenon a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:GradingApproach a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:ReliabilityEstimationMethod a owl:Class ; rdfs:subClassOf ea:EducationalConcept .

#################################################################
# OBJECT PROPERTIES
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityCategory .

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ObjectivityCategory .

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory ;
  rdfs:comment "Corpus notes that 'each method can be used to grade the same test paper', suggesting a single test's content could in principle be interpreted under multiple referencing schemes even though this property is modeled as functional per assessment-instance classification." .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:hasStakeLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakeCategory .

ea:hasScoreInterpretation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:ScoreInterpretationCategory .

ea:hasContext a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ContextCategory .

ea:hasPerformanceFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:PerformanceFormatCategory .

ea:hasMeasurementTiming a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ; rdfs:range ea:TimingCategory .

ea:hasTransferDistance a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferDistanceCategory .

ea:hasTransferValence a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferValenceCategory .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:TestItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:hasKey a owl:ObjectProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Key .

ea:hasDistractor a owl:ObjectProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Distractor .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

ea:isLearningOutcomeOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasLearningOutcome ;
  rdfs:domain ea:LearningOutcome ; rdfs:range ea:Assessment .

ea:hasNormGroup a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:NormReferencedTest ; rdfs:range ea:NormGroup .

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Validity .

ea:hasReliability a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .

ea:hasTestTaker a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:TestTaker .

ea:hasExaminer a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:Examiner .

ea:hasProctor a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:Proctor .

#################################################################
# DATATYPE PROPERTIES
#################################################################

ea:hasReliabilityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range xsd:decimal ;
  rdfs:comment "Ranges from 0 (completely unreliable) to 1 (completely reliable); ratio of true score variance to total variance." .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .

ea:hasItemCount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:integer .

ea:hasStem a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range xsd:string .

#################################################################
# CLASSIFICATION CATEGORIES (VALUE PARTITIONS)
#################################################################

ea:GranularityCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:GranularityCategory owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

ea:PurposeCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:ObjectivityCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ReferencingCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf
  ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:FormalityCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:LocusCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:StandardizationCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StakeCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakeCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakeCategory .
ea:StakeCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:ScoreInterpretationCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:NormReferencedInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretationCategory .
ea:CriterionReferencedInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretationCategory .
ea:ScoreInterpretationCategory owl:disjointUnionOf
  ( ea:NormReferencedInterpretation ea:CriterionReferencedInterpretation ) .

ea:ContextCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:RealisticContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .
ea:SchoolContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .
ea:ContextCategory owl:disjointUnionOf ( ea:RealisticContext ea:SchoolContext ) .

ea:PerformanceFormatCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:ProductFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceEventFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormatCategory owl:disjointUnionOf ( ea:ProductFormat ea:PerformanceEventFormat ) .

ea:TimingCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:SameTimeTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:LaterTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:TimingCategory owl:disjointUnionOf ( ea:SameTimeTiming ea:LaterTiming ) .

ea:TransferDistanceCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:NearTransferDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:FarTransferDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:TransferDistanceCategory owl:disjointUnionOf ( ea:NearTransferDistance ea:FarTransferDistance ) .

ea:TransferValenceCategory a owl:Class ; rdfs:subClassOf ea:ClassificationCategory .
ea:PositiveTransferValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:NegativeTransferValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:TransferValenceCategory owl:disjointUnionOf ( ea:PositiveTransferValence ea:NegativeTransferValence ) .

#################################################################
# CORE ASSESSMENT / TEST TAXONOMY
#################################################################

ea:Test a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "An examination (exam or evaluation), or test, is an educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification." .

ea:Examination a owl:Class ; owl:equivalentClass ea:Test ;
  skos:altLabel "exam", "evaluation" .

ea:WrittenTest a owl:Class ; rdfs:subClassOf ea:Test .

# --- Purpose axis bridges ---
ea:PlacementAssessment a owl:Class ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  skos:altLabel "formative evaluation", "formative feedback", "assessment for learning", "educative assessment", "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] .

# Coordinate-list disjointness claims (corpus: "divided into initial, formative, and summative"
# and, separately, "Placement, formative, summative and diagnostic assessment")
[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ) .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

# Subordination claim (corpus: "A common form of formative assessment is diagnostic assessment")
ea:DiagnosticAssessment rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: the corpus both lists Diagnostic assessment as a coordinate sibling of Placement/Formative/Summative assessment (disjoint partition) AND states diagnostic assessment is 'a common form of formative assessment' (subsumption). Both claims are encoded per corpus; this makes DiagnosticAssessment logically unsatisfiable under strict reasoning, which is intentional documentation of the source conflict rather than a resolved model." .

ea:SelfAssessment a owl:Class ; rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment." .

ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to evaluate whether students are on track for future summative performance; corpus notes ongoing debate on whether interim assessment should be classified as formative or summative." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "May be formative or summative; used across a school/district for consistency." .

# --- Objectivity axis bridges ---
ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveAssessment ea:SubjectiveAssessment ) .

# --- Referencing axis bridges ---
ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

ea:StandardsBasedAssessment a owl:Class ; owl:equivalentClass ea:CriterionReferencedAssessment ;
  rdfs:comment "Criterion-referenced tests 'have also been called standards-based assessments'." .

# --- Formality axis bridges ---
ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:FormalAssessment ea:InformalAssessment ) .

# --- Locus axis bridges ---
ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:InternalAssessment ea:ExternalAssessment ) .

# --- Standardization axis bridges (on Test) ---
ea:StandardizedTest a owl:Class ;
  skos:altLabel "standardized assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:StandardizedTest ea:NonStandardizedTest ) .

# --- Stakes axis bridges (on Test) ---
ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakeLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakeLevel ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:HighStakesTest ea:LowStakesTest ) .

# --- Score interpretation axis bridges (on Test) ---
ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  rdfs:subClassOf ea:NormReferencedAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasScoreInterpretation ; owl:someValuesFrom ea:NormReferencedInterpretation ] ) ] ;
  rdfs:comment "NOTE: the corpus classifies norm-referencing both as a general Assessment-level 'referencing' axis (criterion/norm/ipsative, coordinate with objective/subjective, formal/informal etc.) and separately as a Test-level 'score interpretation' type. Both are modeled; NormReferencedTest is a subclass of the Assessment-level NormReferencedAssessment." .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  rdfs:subClassOf ea:CriterionReferencedAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasScoreInterpretation ; owl:someValuesFrom ea:CriterionReferencedInterpretation ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:NormReferencedTest ea:CriterionReferencedTest ) .

ea:MasteryTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionReferencedTest
      [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A criterion-referenced test that involves a cutscore; the examinee passes if their score exceeds the cutscore." .

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:NormReferencedTest ea:HighStakesTest ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

ea:MidtermExam a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Midterm exams are a type of formative or summative assessment." .

ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Test, ea:SummativeAssessment .

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test, ea:FormativeAssessment .

# --- Context axis bridge: Authentic assessment ---
ea:AuthenticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasContext ; owl:someValuesFrom ea:RealisticContext ] ) ] ;
  rdfs:comment "The measurement of accomplishments within a realistic, practical context that is relevant outside of the school setting." .

# --- Performance-based assessment ---
ea:PerformanceBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  skos:altLabel "performance test", "performance assessment" ;
  rdfs:subClassOf ea:AssessmentTool ;
  rdfs:comment "Requires an examinee to actually perform a task or solve a real-world problem, as opposed to simply answering questions; similar to summative assessment in that it focuses on achievement. Performance formats are further classified into products and performances via hasPerformanceFormat." .
ea:AuthenticAssessment rdfs:subClassOf ea:PerformanceBasedAssessment .

ea:StudentPortfolio a owl:Class ; rdfs:subClassOf ea:PerformanceBasedAssessment ;
  skos:altLabel "digital portfolio", "e-portfolio" .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:StudentPortfolio .

#################################################################
# TEST ITEMS
#################################################################

ea:TestItem a owl:Class ; rdfs:subClassOf ea:AssessmentTool .
ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ; skos:altLabel "MCQ" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:MultipleChoiceItem ea:MultipleResponseItem ea:TrueFalseItem ea:MatchingItem ) .

ea:OneBestAnswerItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem .
ea:SelectAllThatApplyItem a owl:Class ; rdfs:subClassOf ea:MultipleResponseItem ;
  skos:altLabel "True/False family item" ;
  rdfs:comment "Corpus names two 'families' of multiple-choice question: a True/False family requiring selection of all appropriate answers (modeled here as a multiple-response item) and a One-Best-Answer family requiring a single answer. This reuses the term 'True/False' in a different sense from the separate TrueFalseItem class." .

ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "free response question", "FRQ", "extended-response item" .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:MathematicsItem a owl:Class ; rdfs:subClassOf ea:TestItem .

ea:AnswerOption a owl:Class ; rdfs:subClassOf ea:AssessmentTool .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:AnswerOption owl:disjointUnionOf ( ea:Key ea:Distractor ) .

ea:MultipleChoiceItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ;
    owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ;
    owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with multiple-choice items." .

ea:ItemBank a owl:Class ; rdfs:subClassOf ea:AssessmentTool .

#################################################################
# RUBRICS AND GRADING
#################################################################

ea:Rubric a owl:Class ; rdfs:subClassOf ea:AssessmentTool ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric .

[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .

ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: rubrics are classified as a coordinate 3-way list (holistic, analytic, developmental) in one passage, but another passage states 'Developmental rubrics, a subset of analytical rubrics'. Both the disjoint partition and the subsumption are encoded." .

ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Trains raters to score against a rubric with multiple criteria; comes close to analytic scoring methods but 'remains holistic at heart' since raters take all traits into account before a single final score." .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ; rdfs:subClassOf ea:AssessmentQuality ;
  rdfs:comment "The degree to which a measurement tool measures what it claims to measure." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConsequentialValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: validity types are presented as a coordinate list (content, criterion, construct; others: consequential, face) in one passage, while another states 'Construct validity ... subsumes all other types of validity'. Both the disjoint partition and the subsumption (subClassOf) are encoded, documenting the conflict." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
