ea:SplitHalfMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:InternalConsistencyMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:ReliabilityEstimationMethod owl:disjointUnionOf
  ( ea:TestRetestMethod ea:ParallelFormsMethod ea:SplitHalfMethod ea:InternalConsistencyMethod ) .

#################################################################
