ea:TestAnxiety a owl:Class ; rdfs:subClassOf ea:EducationalPhenomenon .
ea:TeachingToTheTest a owl:Class ; rdfs:subClassOf ea:EducationalPhenomenon .
ea:Cheating a owl:Class ; rdfs:subClassOf ea:EducationalPhenomenon .

#################################################################
# LEARNING TYPES
#################################################################

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .
ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .
